      {
        selected =
            show_deck(0, your_hand, i - index, "Choose a card to reveal", 0, ENGINE_DONE_LABEL);
        if ((selected == -1) || (new_make_test(player, your_hand[selected], -1, this_test) == 0))
          break;
        revealed[index] = your_hand[selected];
        if (selected < i)
        {
          shift = your_hand + selected;
          do
          {
            next_shift = shift + 1;
            *shift = shift[1];
            shift = next_shift;
          } while (your_hand + i != next_shift);
        }
        index = index + 1;
      } while (i != index);
      if (index > 0)
        show_deck(0, revealed, index, "Player revealed these cards", 0, ENGINE_DONE_LABEL);
      return index;
    }
    active_count = active_cards_count[player];
  }
  if (active_count < 1)
  {
    return 0;
  }
  i = 0;
  index = 0;
